export function getMarketGoldenScenarioRuleSetSnapshot(asOfIso = at): MarketGoldenScenarioRuleSetSnapshot { getAssetDirectionResolutionCoverageReport(asOfIso); getFxRelativeStrengthCoverageReport(asOfIso); getMacroSurpriseCoverageReport(asOfIso); getMarketContradictionCoverageReport(asOfIso); getMarketConfidenceCalibrationCoverageReport(asOfIso); getMarketPriceReactionCoverageReport(asOfIso); getMarketProviderReliabilityCoverageReport(asOfIso); return { generatedAt:asOfIso, rules:[...rules], scenarioCount:fixtures.length, launchAssets:[...MARKET_GOLDEN_SCENARIO_ASSETS], warnings:['fixture_driven_acceptance_only','live_provider_activation_pending','empirical_backtesting_pending','production_data_calibration_pending'], complete:false, pending }; }
export function assertMarketGoldenScenarioRuleSetValid(): MarketGoldenScenarioRuleSetSnapshot { const snapshot = getMarketGoldenScenarioRuleSetSnapshot(); const coverage = getMarketGoldenScenarioCoverageReport(); const missing = allEngines.filter((engine) => !coverage.enginesCovered.includes(engine)); if (fixtures.length < 28) throw new Error('market_golden_scenarios_minimum_not_met'); if (coverage.missingAssets.length) throw new Error(`market_golden_scenarios_missing_assets:${coverage.missingAssets.join(',')}`); if (missing.length) throw new Error(`market_golden_scenarios_missing_engines:${missing.join(',')}`); const failed = runMarketGoldenScenarioSuite().results.filter((x) => !x.pass); if (failed.length) throw new Error(`market_golden_scenarios_failed:${failed.map((x) => x.scenarioId).join(',')}`); return snapshot; }
export function listMarketGoldenScenarioRules(asset?: MarketGoldenScenarioAsset): MarketGoldenScenarioRule[] { return rules.filter((rule) => !asset || !rule.asset || rule.asset === asset).map((rule) => ({ ...rule, requiredScenarioIds:[...rule.requiredScenarioIds] })); }
export function listMarketGoldenScenarioWarnings(asset?: MarketGoldenScenarioAsset): string[] { const scenarios = listMarketGoldenScenarios().filter((x) => !asset || x.asset === asset); return [...new Set(scenarios.flatMap(resultWarnings))].sort(); }
